using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace Devian
{
    public enum ScrollDirection { Vertical, Horizontal }

    /// <summary>
    /// 세로/가로 스크롤 혼합 레이아웃 컨테이너.
    /// UIComponentBase를 상속하여 UICanvas 수명주기에 통합된다.
    /// onInit(): ScrollRect 캐시 + 이벤트 등록.
    /// onInitComplete(): Section 수집 → 레이아웃 → 가상화 시작.
    /// </summary>
    [RequireComponent(typeof(ScrollRect))]
    public class UIComponentScrollContainer : UIComponentBase
    {
        // ────────────────────────────────────────────
        // Inspector
        // ────────────────────────────────────────────

        [Header("Direction")]
        [SerializeField] private ScrollDirection _direction = ScrollDirection.Vertical;

        [Header("Layout")]
        [SerializeField] private RectOffset _padding = new RectOffset();
        [SerializeField] private float _sectionSpacing = 10f;

        [Header("Virtualization")]
        [SerializeField] private int _bufferRows = 2;

        // ────────────────────────────────────────────
        // Scroll Position API
        // ────────────────────────────────────────────

        /// <summary>초기화 여부.</summary>
        public bool IsInitialized => _initialized;

        /// <summary>
        /// 전체 스크롤 가능 영역 크기 (Vertical=높이, Horizontal=폭).
        /// </summary>
        public float ScrollHeight => _totalContentSize;

        /// <summary>
        /// 현재 스크롤 위치. 0 = 시작점 (Vertical=최상단, Horizontal=최좌측).
        /// </summary>
        public float ScrollPosition
        {
            get => GetScrollPosition();
            set => SetScrollPosition(value);
        }

        /// <summary>
        /// 최대 스크롤 위치. Content가 Viewport보다 클 때만 양수.
        /// </summary>
        public float MaxScrollPosition
            => Mathf.Max(0f, _totalContentSize - GetViewportSize());

        // ────────────────────────────────────────────
        // UIComponentBase Lifecycle
        // ────────────────────────────────────────────

        /// <summary>
        /// Phase 1: ScrollRect 캐시 + Content anchor/pivot 강제 + 이벤트 등록.
        /// Frame.onInit() 이전에 호출된다.
        /// </summary>
        protected override void onInit()
        {
            _scrollRect = GetComponent<ScrollRect>();
            _content = _scrollRect.content;
            _viewport = _scrollRect.viewport;

            // Content의 anchor/pivot을 top-left로 강제
            _content.anchorMin = new Vector2(0f, 1f);
            _content.anchorMax = new Vector2(0f, 1f);
            _content.pivot = new Vector2(0f, 1f);

            _scrollRect.onValueChanged.AddListener(OnScrollChanged);
        }

        /// <summary>
        /// Phase 4: Section 수집 → 레이아웃 → 가상화 시작.
        /// Frame.onInit()에서 Grid 설정이 완료된 후 호출된다.
        /// </summary>
        protected override void onInitComplete()
        {
            CollectSections();
            BuildLayoutRows();
            RecalculateContentSize();
            ApplySectionLayout();

            _initialized = true;
            UpdateVisibleRows();
        }

        // ────────────────────────────────────────────
        // MonoBehaviour
        // ────────────────────────────────────────────

        private void OnDestroy()
        {
            if (_initialized)
            {
                Clear();
            }
        }

        // ────────────────────────────────────────────
        // Public API
        // ────────────────────────────────────────────

        /// <summary>
        /// 모든 보이는 항목을 재바인딩한다.
        /// </summary>
        public void Refresh()
        {
            if (!_initialized) return;

            foreach (var kvp in _activeCells)
            {
                int rowIdx = kvp.Key / MAX_COLUMNS;
                int colIdx = kvp.Key % MAX_COLUMNS;
                var row = _layoutRows[rowIdx];
                if (row.Type == LayoutRow.RowType.CellRow)
                {
                    int localIndex = row.LocalStartIndex + colIdx;
                    row.Grid.onUnbindCell?.Invoke(kvp.Value);
                    row.Grid.onBindCell?.Invoke(kvp.Value, localIndex);
                }
            }

            foreach (var section in _sections)
            {
                if (section is UIPlugInScrollFrame frame && frame.IsActive)
                {
                    frame.onUnbind?.Invoke(frame);
                    frame.onBind?.Invoke(frame);
                }
            }
        }

        /// <summary>
        /// 레이아웃을 재계산한다.
        /// Grid.SetCellCount() 변경, Frame 추가/제거 등 구조 변경 후 호출.
        /// 활성 셀 전부 Despawn → Section 재수집 → 레이아웃 재빌드 → 가상화 재시작.
        /// </summary>
        public void Rebuild()
        {
            if (!_initialized) return;

            // 활성 셀 전부 Despawn
            foreach (var kvp in _activeCells)
            {
                DespawnGridCell(kvp.Key, kvp.Value);
            }
            _activeCells.Clear();

            // Frame 비활성화
            foreach (var section in _sections)
            {
                if (section is UIPlugInScrollFrame frame)
                {
                    if (frame.IsActive)
                    {
                        frame.onUnbind?.Invoke(frame);
                    }
                    frame.gameObject.SetActive(false);
                    frame.IsActive = false;
                }
            }

            // Grid config holder 재활성화 (CollectSections이 찾을 수 있도록)
            foreach (var section in _sections)
            {
                if (section is UIPlugInScrollGrid grid)
                {
                    grid.gameObject.SetActive(true);
                }
            }

            // 재빌드
            _prevFirstRow = -1;
            _prevLastRow = -1;
            CollectSections();
            BuildLayoutRows();
            RecalculateContentSize();
            ApplySectionLayout();
            UpdateVisibleRows();
        }

        /// <summary>
        /// 특정 Grid의 셀이 보이도록 스크롤한다.
        /// </summary>
        public void ScrollTo(UIPlugInScrollGrid grid, int localIndex)
        {
            if (!_initialized) return;

            int targetRowInGrid = localIndex / grid.ColumnCount;
            int layoutRowIndex = grid.FirstLayoutRowIndex + targetRowInGrid;
            if (layoutRowIndex < 0 || layoutRowIndex >= _layoutRows.Count) return;

            ScrollPosition = _layoutRows[layoutRowIndex].MainAxisPosition;
        }

        /// <summary>
        /// 특정 Frame이 보이도록 스크롤한다.
        /// </summary>
        public void ScrollTo(UIPlugInScrollFrame frame)
        {
            if (!_initialized) return;
            if (frame.LayoutRowIndex < 0 || frame.LayoutRowIndex >= _layoutRows.Count) return;

            ScrollPosition = _layoutRows[frame.LayoutRowIndex].MainAxisPosition;
        }

        /// <summary>
        /// 모든 셀을 Despawn하고 상태를 초기화한다.
        /// </summary>
        public void Clear()
        {
            // Grid 셀 전부 Despawn
            foreach (var kvp in _activeCells)
            {
                int rowIdx = kvp.Key / MAX_COLUMNS;
                var row = _layoutRows[rowIdx];
                if (row.Type == LayoutRow.RowType.CellRow)
                {
                    row.Grid.onUnbindCell?.Invoke(kvp.Value);
                }
                kvp.Value.CellIndex = -1;
                BundlePool.Despawn(kvp.Value);
            }
            _activeCells.Clear();

            // Frame 비활성화
            foreach (var section in _sections)
            {
                if (section is UIPlugInScrollFrame frame)
                {
                    if (frame.IsActive)
                    {
                        frame.onUnbind?.Invoke(frame);
                    }
                    frame.gameObject.SetActive(false);
                    frame.IsActive = false;
                }
            }

            // Grid config holder 재활성화
            foreach (var section in _sections)
            {
                if (section is UIPlugInScrollGrid grid)
                {
                    grid.gameObject.SetActive(true);
                }
            }

            // 상태 초기화
            if (_scrollRect != null)
            {
                _scrollRect.onValueChanged.RemoveListener(OnScrollChanged);
            }
            _sections.Clear();
            _layoutRows.Clear();
            _prevFirstRow = -1;
            _prevLastRow = -1;
            _initialized = false;
            _totalContentSize = 0f;
            SetContentMainAxisSize(0f);
        }

        // ────────────────────────────────────────────
        // Internal State
        // ────────────────────────────────────────────

        private const int MAX_COLUMNS = 64;

        private ScrollRect _scrollRect;
        private RectTransform _content;
        private RectTransform _viewport;
        private float _totalContentSize;

        private readonly List<MonoBehaviour> _sections = new List<MonoBehaviour>();
        private readonly List<LayoutRow> _layoutRows = new List<LayoutRow>();
        private readonly Dictionary<int, UIPlugInScrollCell> _activeCells
            = new Dictionary<int, UIPlugInScrollCell>();

        private int _prevFirstRow = -1;
        private int _prevLastRow = -1;
        private bool _initialized;

        // ────────────────────────────────────────────
        // LayoutRow
        // ────────────────────────────────────────────

        private struct LayoutRow
        {
            public enum RowType { CellRow, FrameRow }

            public RowType Type;
            public float MainAxisPosition;
            public float Height;
            public int RowIndex;

            // CellRow
            public UIPlugInScrollGrid Grid;
            public int LocalStartIndex;
            public int CellCountInRow;

            // FrameRow
            public UIPlugInScrollFrame Frame;
        }

        // ────────────────────────────────────────────
        // Section Collection
        // ────────────────────────────────────────────

        private void CollectSections()
        {
            _sections.Clear();

            for (int i = 0; i < _content.childCount; i++)
            {
                var child = _content.GetChild(i);

                var grid = child.GetComponent<UIPlugInScrollGrid>();
                if (grid != null)
                {
                    _sections.Add(grid);
                    continue;
                }

                var frame = child.GetComponent<UIPlugInScrollFrame>();
                if (frame != null)
                {
                    _sections.Add(frame);
                }
            }
        }

        // ────────────────────────────────────────────
        // Layout Building
        // ────────────────────────────────────────────

        private void BuildLayoutRows()
        {
            _layoutRows.Clear();

            float currentPos = _padding.top;
            int rowIndex = 0;

            for (int i = 0; i < _sections.Count; i++)
            {
                var section = _sections[i];

                if (section is UIPlugInScrollGrid grid)
                {
                    grid.SectionIndex = i;
                    grid.RowCount = grid.CellCount > 0
                        ? Mathf.CeilToInt(grid.CellCount / (float)grid.ColumnCount)
                        : 0;
                    grid.FirstLayoutRowIndex = rowIndex;

                    for (int r = 0; r < grid.RowCount; r++)
                    {
                        int cellsInRow = Mathf.Min(
                            grid.ColumnCount,
                            grid.CellCount - r * grid.ColumnCount);

                        _layoutRows.Add(new LayoutRow
                        {
                            Type = LayoutRow.RowType.CellRow,
                            MainAxisPosition = currentPos,
                            Height = grid.CellSize.y,
                            RowIndex = rowIndex,
                            Grid = grid,
                            LocalStartIndex = r * grid.ColumnCount,
                            CellCountInRow = cellsInRow
                        });

                        currentPos += grid.CellSize.y;
                        if (r < grid.RowCount - 1)
                        {
                            currentPos += grid.Spacing.y;
                        }
                        rowIndex++;
                    }

                    grid.TotalHeight = grid.RowCount > 0
                        ? grid.RowCount * grid.CellSize.y
                          + (grid.RowCount - 1) * grid.Spacing.y
                        : 0f;
                }
                else if (section is UIPlugInScrollFrame frame)
                {
                    frame.SectionIndex = i;
                    frame.LayoutRowIndex = rowIndex;

                    _layoutRows.Add(new LayoutRow
                    {
                        Type = LayoutRow.RowType.FrameRow,
                        MainAxisPosition = currentPos,
                        Height = frame.Height,
                        RowIndex = rowIndex,
                        Frame = frame
                    });

                    currentPos += frame.Height;
                    rowIndex++;
                }

                // Section 간 간격 (마지막 제외)
                if (i < _sections.Count - 1)
                {
                    currentPos += _sectionSpacing;
                }
            }

            _totalContentSize = currentPos + _padding.bottom;
        }

        private void RecalculateContentSize()
        {
            SetContentMainAxisSize(_totalContentSize);
        }

        private void ApplySectionLayout()
        {
            foreach (var section in _sections)
            {
                if (section is UIPlugInScrollGrid grid)
                {
                    grid.gameObject.SetActive(false);
                }
                else if (section is UIPlugInScrollFrame frame)
                {
                    var rt = (RectTransform)frame.transform;
                    SetFramePosition(rt, frame.LayoutRowIndex);
                    frame.gameObject.SetActive(false);
                    frame.IsActive = false;
                }
            }
        }

        // ────────────────────────────────────────────
        // Virtualization
        // ────────────────────────────────────────────

        private void OnScrollChanged(Vector2 normalizedPos)
        {
            if (!_initialized) return;
            UpdateVisibleRows();
        }

        private void UpdateVisibleRows()
        {
            if (_layoutRows.Count == 0) return;

            float scrollPos = GetScrollPosition();
            float viewportSize = GetViewportSize();

            int firstRow = FindFirstVisibleRow(scrollPos);
            int lastRow = FindLastVisibleRow(scrollPos, viewportSize);

            firstRow = Mathf.Max(0, firstRow - _bufferRows);
            lastRow = Mathf.Min(_layoutRows.Count - 1, lastRow + _bufferRows);

            var keysToRemove = new List<int>();
            foreach (var kvp in _activeCells)
            {
                int rowIdx = kvp.Key / MAX_COLUMNS;
                if (rowIdx < firstRow || rowIdx > lastRow)
                {
                    DespawnGridCell(kvp.Key, kvp.Value);
                    keysToRemove.Add(kvp.Key);
                }
            }
            for (int i = 0; i < keysToRemove.Count; i++)
            {
                _activeCells.Remove(keysToRemove[i]);
            }

            for (int r = firstRow; r <= lastRow; r++)
            {
                var row = _layoutRows[r];

                if (row.Type == LayoutRow.RowType.CellRow)
                {
                    for (int c = 0; c < row.CellCountInRow; c++)
                    {
                        int key = row.RowIndex * MAX_COLUMNS + c;
                        if (!_activeCells.ContainsKey(key))
                        {
                            SpawnGridCell(row, c, key);
                        }
                    }
                }
                else
                {
                    if (!row.Frame.IsActive)
                    {
                        row.Frame.gameObject.SetActive(true);
                        row.Frame.IsActive = true;
                        row.Frame.onBind?.Invoke(row.Frame);
                    }
                }
            }

            foreach (var section in _sections)
            {
                if (section is UIPlugInScrollFrame frame && frame.IsActive)
                {
                    if (frame.LayoutRowIndex < firstRow || frame.LayoutRowIndex > lastRow)
                    {
                        frame.onUnbind?.Invoke(frame);
                        frame.gameObject.SetActive(false);
                        frame.IsActive = false;
                    }
                }
            }

            _prevFirstRow = firstRow;
            _prevLastRow = lastRow;
        }

        // ────────────────────────────────────────────
        // Spawn / Despawn
        // ────────────────────────────────────────────

        private static readonly Vector2 TopLeft = new Vector2(0f, 1f);

        private void SpawnGridCell(LayoutRow row, int colIndex, int key)
        {
            int localIndex = row.LocalStartIndex + colIndex;
            var cell = BundlePool.Spawn<UIPlugInScrollCell>(
                row.Grid.CellPrefabName,
                Vector3.zero,
                Quaternion.identity,
                _content);

            var rt = cell.Rt;
            rt.anchorMin = TopLeft;
            rt.anchorMax = TopLeft;
            rt.pivot = TopLeft;
            rt.sizeDelta = row.Grid.CellSize;
            rt.anchoredPosition = CalcCellPosition(row, colIndex);

            cell.CellIndex = localIndex;
            row.Grid.onBindCell?.Invoke(cell, localIndex);
            _activeCells[key] = cell;
        }

        private void DespawnGridCell(int key, UIPlugInScrollCell cell)
        {
            int rowIdx = key / MAX_COLUMNS;
            var row = _layoutRows[rowIdx];
            if (row.Type == LayoutRow.RowType.CellRow)
            {
                row.Grid.onUnbindCell?.Invoke(cell);
            }
            cell.CellIndex = -1;
            BundlePool.Despawn(cell);
        }

        // ────────────────────────────────────────────
        // Binary Search
        // ────────────────────────────────────────────

        private int FindFirstVisibleRow(float scrollPos)
        {
            int lo = 0, hi = _layoutRows.Count - 1;
            while (lo < hi)
            {
                int mid = (lo + hi) / 2;
                if (_layoutRows[mid].MainAxisPosition + _layoutRows[mid].Height <= scrollPos)
                    lo = mid + 1;
                else
                    hi = mid;
            }
            return lo;
        }

        private int FindLastVisibleRow(float scrollPos, float viewportSize)
        {
            float endEdge = scrollPos + viewportSize;
            int lo = 0, hi = _layoutRows.Count - 1;
            while (lo < hi)
            {
                int mid = (lo + hi + 1) / 2;
                if (_layoutRows[mid].MainAxisPosition >= endEdge)
                    hi = mid - 1;
                else
                    lo = mid;
            }
            return lo;
        }

        // ────────────────────────────────────────────
        // Axis Helpers
        // ────────────────────────────────────────────

        private float GetViewportSize()
        {
            return _direction == ScrollDirection.Vertical
                ? _viewport.rect.height
                : _viewport.rect.width;
        }

        private float GetCrossAxisSize()
        {
            return _direction == ScrollDirection.Vertical
                ? _viewport.rect.width
                : _viewport.rect.height;
        }

        private float GetScrollPosition()
        {
            if (_content == null) return 0f;
            return _direction == ScrollDirection.Vertical
                ? _content.anchoredPosition.y
                : -_content.anchoredPosition.x;
        }

        private void SetScrollPosition(float pos)
        {
            pos = Mathf.Clamp(pos, 0f, MaxScrollPosition);
            var ap = _content.anchoredPosition;
            if (_direction == ScrollDirection.Vertical)
                ap.y = pos;
            else
                ap.x = -pos;
            _content.anchoredPosition = ap;
            UpdateVisibleRows();
        }

        private void SetContentMainAxisSize(float size)
        {
            if (_content == null) return;
            var sd = _content.sizeDelta;
            if (_direction == ScrollDirection.Vertical)
                sd.y = size;
            else
                sd.x = size;
            _content.sizeDelta = sd;
        }

        private Vector2 CalcCellPosition(LayoutRow row, int colIndex)
        {
            float crossSize = row.Grid.CellSize.x + row.Grid.Spacing.x;
            float cross = colIndex * crossSize;
            float main = row.MainAxisPosition;

            if (_direction == ScrollDirection.Vertical)
            {
                return new Vector2(cross, -main);
            }
            else
            {
                return new Vector2(main, -cross);
            }
        }

        private void SetFramePosition(RectTransform rt, int layoutRowIndex)
        {
            var row = _layoutRows[layoutRowIndex];
            float crossAxisSize = GetCrossAxisSize();

            rt.anchorMin = TopLeft;
            rt.anchorMax = TopLeft;
            rt.pivot = TopLeft;

            if (_direction == ScrollDirection.Vertical)
            {
                rt.anchoredPosition = new Vector2(0, -row.MainAxisPosition);
                rt.sizeDelta = new Vector2(crossAxisSize, row.Height);
            }
            else
            {
                rt.anchoredPosition = new Vector2(row.MainAxisPosition, 0);
                rt.sizeDelta = new Vector2(row.Height, crossAxisSize);
            }
        }
    }
